-- V23: hot-path indexes guarded by column existence so rollout remains migration-safe across environments.
do $$begin
 if exists(select 1 from information_schema.columns where table_schema='public' and table_name='orders' and column_name='status') and exists(select 1 from information_schema.columns where table_schema='public' and table_name='orders' and column_name='created_at') then execute 'create index if not exists orders_status_created_at_idx on public.orders(status,created_at desc)';end if;
 if exists(select 1 from information_schema.columns where table_schema='public' and table_name='orders' and column_name='customer_id') and exists(select 1 from information_schema.columns where table_schema='public' and table_name='orders' and column_name='created_at') then execute 'create index if not exists orders_customer_created_at_idx on public.orders(customer_id,created_at desc)';end if;
 if exists(select 1 from information_schema.columns where table_schema='public' and table_name='order_operations' and column_name='operational_status') and exists(select 1 from information_schema.columns where table_schema='public' and table_name='order_operations' and column_name='updated_at') then execute 'create index if not exists order_operations_status_updated_idx on public.order_operations(operational_status,updated_at desc)';end if;
 if exists(select 1 from information_schema.columns where table_schema='public' and table_name='inventory_reservations' and column_name='status') and exists(select 1 from information_schema.columns where table_schema='public' and table_name='inventory_reservations' and column_name='variant_id') then execute 'create index if not exists inventory_reservations_status_variant_idx on public.inventory_reservations(status,variant_id)';end if;
 if exists(select 1 from information_schema.columns where table_schema='public' and table_name='observability_events' and column_name='occurred_at') and exists(select 1 from information_schema.columns where table_schema='public' and table_name='observability_events' and column_name='severity') then execute 'create index if not exists observability_events_time_severity_idx on public.observability_events(occurred_at desc,severity)';end if;
 if exists(select 1 from information_schema.columns where table_schema='public' and table_name='loyalty_ledger' and column_name='customer_id') and exists(select 1 from information_schema.columns where table_schema='public' and table_name='loyalty_ledger' and column_name='occurred_at') then execute 'create index if not exists loyalty_ledger_customer_time_idx on public.loyalty_ledger(customer_id,occurred_at desc)';end if;
 if exists(select 1 from information_schema.columns where table_schema='public' and table_name='post_release_sessions' and column_name='status') and exists(select 1 from information_schema.columns where table_schema='public' and table_name='post_release_sessions' and column_name='started_at') then execute 'create index if not exists post_release_sessions_status_started_idx on public.post_release_sessions(status,started_at desc)';end if;
 if exists(select 1 from information_schema.columns where table_schema='public' and table_name='recovery_drills' and column_name='status') and exists(select 1 from information_schema.columns where table_schema='public' and table_name='recovery_drills' and column_name='planned_at') then execute 'create index if not exists recovery_drills_status_planned_idx on public.recovery_drills(status,planned_at desc)';end if;
end$$;
